func runAncestors(args []string) int {
	fs := flag.NewFlagSet("ancestors", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	specPath := fs.String("spec", "", "path to spec file")
	jobName := fs.String("job", "", "target job")
