		return 2
	}

	ancestorSet := computeAncestorSet(spec, target)

	levels := computeLevels(spec)
	var ordered []string
	for _, names := range levels {
		for _, name := range names {
			if ancestorSet[name] {
				ordered = append(ordered, name)
			}
		}
	}

	switch *format {
	case "text":
		if len(ordered) > 0 {
