		}
	case "json":
		out, err := json.Marshal(ordered)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: marshal: %s\n", err)
			return 2
		}
		os.Stdout.Write(out)
		fmt.Println()
	}

	return 0
}

func computeAncestorSet(spec *Spec, target *Job) map[string]bool {
	ancestors := map[string]bool{}
	var visit func(job *Job)
	visit = func(job *Job) {
		for _, dep := range job.Deps {
			if !ancestors[dep] {
				ancestors[dep] = true
				visit(spec.ByName[dep])
			}
		}
		}
	}
	visit(target)
	return ancestors
}
